<?php require_once "../config/auth.php";require_login();$ok="";if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$q=db()->prepare("INSERT INTO tickets(user_id,subject,message) VALUES(?,?,?)");$q->execute([$_SESSION["user_id"],trim($_POST["subject"]),trim($_POST["message"])]);$ok="Ticket submitted."}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><main><form class="box" method="post"><h1>Support</h1><?php if($ok):?><div class="success"><?=$ok?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="subject" placeholder="Subject" required><textarea name="message" placeholder="Message" required></textarea><button>Open Ticket</button></form></main></body></html>